15	// On-disk format (queue.log):
16	//
17	//	magic   = "RELAYPROOF-QUEUE-V1\n"
18	//	frame   = uint32-be payload length(N) | N bytes JSON payload | uint32-be CRC32-IEEE(payload)
19	//
20	// The log is an append-only write-ahead log. Every mutating operation is
21	// persisted as one framed, checksummed record and fsynced before it is
22	// acknowledged; a success record frames the local success entry and the nonce
23	// consumption together, so the two can never take effect separately.
24	//
25	// Crash recovery: a frame missing bytes at end of file, or a final frame with
26	// a bad checksum, is the torn tail of a write that was never acknowledged and
27	// is truncated. Bad checksums or framing anywhere before the end, a foreign
28	// header, or an unsupported version reject the directory with ErrCorrupt;
29	// state is never silently cleared.
30	
31	const (
32		logName          = "queue.log"
33		logMagic         = "RELAYPROOF-QUEUE-V1\n"
34		compactThreshold = 4 << 20 // compact when the active log grows past 4 MiB
35		compactFileMode  = 0o600
36		frameHeaderSize  = 4
37		frameCRCsSize    = 4
38	)
39	
40	var crcTable = crc32.MakeTable(crc32.IEEE)
41	
42	// JSON log entry kinds.
43	const (
44		kindVersion = "version"
45		kindSource  = "source"
46		kindHeader  = "header"
47		kindSubmit  = "submit"
48		kindResult  = "result"
49		kindState   = "state" // compacted snapshot: full status after >=1 attempts
50		kindAdvance = "advance"
51		currentLogV = 1
52	)
53	
54	type logEntry struct {
55		T string `json:"t"`
56		V int    `json:"v,omitempty"`
57	
58		Chain   string `json:"chain,omitempty"`
59		Height  int64  `json:"height,omitempty"`
60		Root    string `json:"root,omitempty"`
61		Trusted bool   `json:"trusted,omitempty"`
62	
63		Seq       int64  `json:"seq,omitempty"`
64		ID        string `json:"id,omitempty"`
65		From      string `json:"from,omitempty"`
66		To        string `json:"to,omitempty"`
67		Nonce     uint64 `json:"nonce,omitempty"`
68		Payload   string `json:"payload,omitempty"`
69		ProofAt   int64  `json:"proofAt,omitempty"`
70		ExpiresAt int64  `json:"expiresAt,omitempty"`
71	
72		Now        int64  `json:"now,omitempty"`
73		Status     string `json:"status,omitempty"`
74		Reason     string `json:"reason,omitempty"`
75		Attempts   int    `json:"attempts,omitempty"`
76		NextRetry  int64  `json:"nextRetry,omitempty"`
77		ConsumeKey string `json:"consumeKey,omitempty"`
78		ConsumeBy  string `json:"consumeBy,omitempty"`
79	}
80	
81	type store struct {
82		dir  string
83		f    *os.File
84		size int64
85		// snap, when set, supplies a live-state snapshot for log compaction.
86		snap func() *loadedState
87		// injectErr is a test hook forcing append to fail after opening the file.
88		injectErr error
89	}
90	
91	// loadedState is the fully replayed (or live) queue state.
92	type loadedState struct {
93		sources  map[string]bool
94		headers  map[string]Header
95		records  map[string]*Record
96		consumed map[string]string
97		nextSeq  int64
98		now      int64
99	}
100	
101	func openStore(dir string) (*store, *loadedState, error) {
102		path := filepath.Join(dir, logName)
103	
104		if _, err := os.Stat(path); err != nil {
105			if !os.IsNotExist(err) {
106				return nil, nil, fmt.Errorf("stat %s: %w", logName, err)
107			}
108			if err := createLog(path, dir); err != nil {
109				return nil, nil, err
110			}
111		} else if err := checkMagic(path); err != nil {
112			return nil, nil, err
113		}
114	
115		raw, err := os.ReadFile(path)
116		if err != nil {
117			return nil, nil, fmt.Errorf("read %s: %w", logName, err)
118		}
119		goodLen, state, err := replayLog(raw)
120		if err != nil {
121			return nil, nil, err
122		}
123		if int64(len(raw)) != goodLen {
124			// Drop the torn tail of an entry that can never have been acknowledged.
125			tf, err := os.OpenFile(path, os.O_RDWR, compactFileMode)
126			if err != nil {
127				return nil, nil, fmt.Errorf("open %s for repair: %w", logName, err)
128			}
129			if err := tf.Truncate(goodLen); err != nil {
130				tf.Close()
131				return nil, nil, fmt.Errorf("truncate torn log tail: %w", err)
132			}
133			if err := tf.Sync(); err != nil {
134				tf.Close()
135				return nil, nil, fmt.Errorf("sync repaired %s: %w", logName, err)
136			}
137			if err := tf.Close(); err != nil {
138				return nil, nil, err
139			}
140			if err := syncDir(dir); err != nil {
141				return nil, nil, err
142			}
143		}
144	
145		f, err := os.OpenFile(path, os.O_RDWR|os.O_APPEND, compactFileMode)
146		if err != nil {
147			return nil, nil, fmt.Errorf("open %s for append: %w", logName, err)
148		}
149		if _, err := f.Seek(0, io.SeekEnd); err != nil {
150			f.Close()
151			return nil, nil, err
152		}
153		return &store{dir: dir, f: f, size: goodLen}, state, nil
154	}
155	
156	func createLog(path, dir string) error {
157		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, compactFileMode)
158		if err != nil {
159			return fmt.Errorf("create %s: %w", logName, err)
160		}
161		frame := encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))
162		if _, err := f.Write(append([]byte(logMagic), frame...)); err != nil {
163			f.Close()
164			return fmt.Errorf("write %s header: %w", logName, err)
165		}
166		if err := f.Sync(); err != nil {
167			f.Close()
168			return fmt.Errorf("sync %s: %w", logName, err)
169		}
170		if err := f.Close(); err != nil {
171			return err
172		}
173		return syncDir(dir)
174	}
175	
176	func mustMarshal(e *logEntry) []byte {
177		b, err := json.Marshal(e)
178		if err != nil {
179			panic(err)
180		}
181		return b
182	}
183	
184	// encodeFrame wraps a payload with its big-endian length and CRC32.
185	func encodeFrame(payload []byte) []byte {
186		frame := make([]byte, 0, frameHeaderSize+len(payload)+frameCRCsSize)
187		var hdr [4]byte
188		binary.BigEndian.PutUint32(hdr[:], uint32(len(payload)))
189		frame = append(frame, hdr[:]...)
190		frame = append(frame, payload...)
191		var crc [4]byte
192		binary.BigEndian.PutUint32(crc[:], crc32.Checksum(payload, crcTable))
193		frame = append(frame, crc[:]...)
194		return frame
195	}
196	
197	func checkMagic(path string) error {
198		f, err := os.Open(path)
199		if err != nil {
200			return fmt.Errorf("open %s: %w", logName, err)
201		}
202		defer f.Close()
203		buf := make([]byte, len(logMagic))
204		n, err := io.ReadFull(f, buf)
205		if err != nil && err != io.ErrUnexpectedEOF && err != io.EOF {
206			return fmt.Errorf("read %s header: %w", logName, err)
207		}
208		if n < len(logMagic) || !bytes.Equal(buf, []byte(logMagic)) {
209			return fmt.Errorf("%w: missing or foreign %s header", ErrCorrupt, logName)
210		}
211		return nil
212	}
213	
214	// replayLog parses and validates the log, returning the byte length of the
215	// longest intact prefix and the reconstructed state.
216	func replayLog(raw []byte) (int64, *loadedState, error) {
217		if !bytes.HasPrefix(raw, []byte(logMagic)) {
218			return 0, nil, fmt.Errorf("%w: missing %s header", ErrCorrupt, logMagic)
219		}
220		pos := len(logMagic)
221		state := &loadedState{
222			sources:  map[string]bool{},
223			headers:  map[string]Header{},
224			records:  map[string]*Record{},
225			consumed: map[string]string{},
226		}
227	
228		sawVersion := false
229		for pos < len(raw) {
230			// Need at least the length header.
231			if len(raw)-pos < frameHeaderSize {
232				return int64(pos), state, nil // torn length header of an unacked write
233			}
234			n := int(binary.BigEndian.Uint32(raw[pos : pos+frameHeaderSize]))
235			if n == 0 {
236				return 0, nil, fmt.Errorf("%w: zero-length record at offset %d", ErrCorrupt, pos)
237			}
238			bodyStart := pos + frameHeaderSize
239			frameEnd := bodyStart + n + frameCRCsSize
240			if frameEnd > len(raw) {
241				return int64(pos), state, nil // torn body/CRC of an unacked write
242			}
243			payload := raw[bodyStart : bodyStart+n]
244			wantCRC := binary.BigEndian.Uint32(raw[bodyStart+n : frameEnd])
245			if crc32.Checksum(payload, crcTable) != wantCRC {
246				if frameEnd == len(raw) {
247					// Torn sectors of the final, unacknowledged frame.
248					return int64(pos), state, nil
249				}
250				return 0, nil, fmt.Errorf("%w: checksum mismatch at offset %d", ErrCorrupt, pos)
251			}
252			var e logEntry
253			if err := json.Unmarshal(payload, &e); err != nil {
254				return 0, nil, fmt.Errorf("%w: invalid record at offset %d: %v", ErrCorrupt, pos, err)
255			}
256			if !sawVersion {
257				if e.T != kindVersion || e.V != currentLogV {
258					return 0, nil, fmt.Errorf("%w: unsupported log version entry: %+v", ErrCorrupt, e)
259				}
260				sawVersion = true
261			} else if e.T == kindVersion {
262				return 0, nil, fmt.Errorf("%w: unexpected version record at offset %d", ErrCorrupt, pos)
263			} else if err := applyEntry(state, &e); err != nil {
264				return 0, nil, err
265			}
266			pos = frameEnd
267		}
268		if !sawVersion {
269			return 0, nil, fmt.Errorf("%w: missing version record", ErrCorrupt)
270		}
271		return int64(pos), state, nil
272	}
273	
274	func applyEntry(s *loadedState, e *logEntry) error {
275		corrupt := func(msg string, args ...any) error {
276			return fmt.Errorf("%w: %s", ErrCorrupt, fmt.Sprintf(msg, args...))
277		}
278		switch e.T {
279		case kindSource:
280			if e.Chain == "" {
281				return corrupt("source entry with empty chain")
282			}
283			s.sources[e.Chain] = true
284		case kindHeader:
285			if e.Chain == "" || e.Height < 0 {
286				return corrupt("bad header entry: %+v", e)
287			}
288			s.headers[e.Chain] = Header{Chain: e.Chain, Height: e.Height, Root: e.Root, Trusted: e.Trusted}
289		case kindSubmit:
290			if e.ID == "" || e.From == "" || e.To == "" || e.ProofAt < 0 || e.ExpiresAt < 0 {
291				return corrupt("bad submit entry: %+v", e)
292			}
293			if _, dup := s.records[e.ID]; dup {
294				return corrupt("duplicate submit for id %q", e.ID)
295			}
296			if e.Seq != s.nextSeq {
297				return corrupt("submit seq %d out of order, expected %d", e.Seq, s.nextSeq)
298			}
299			s.records[e.ID] = &Record{
300				Msg: Envelope{
301					Message: Message{
302						ID:      e.ID,
303						From:    e.From,
304						To:      e.To,
305						Nonce:   e.Nonce,
306						Payload: e.Payload,
307						ProofAt: e.ProofAt,
308					},
309					ExpiresAt: e.ExpiresAt,
310				},
311				Status: StatusPending,
312				Reason: "awaiting first processing",
313				Seq:    e.Seq,
314			}
315			s.nextSeq++
316		case kindResult:
317			rec, ok := s.records[e.ID]
318			if !ok {
319				return corrupt("result for unknown id %q", e.ID)
320			}
321			if isTerminal(rec.Status) {
322				return corrupt("result for terminal id %q", e.ID)
323			}
324			if rec.Attempts > 0 && e.Now < rec.LastProcAt {
325				return corrupt("result time %d before prior time %d for %q", e.Now, rec.LastProcAt, e.ID)
326			}
327			if e.Attempts != rec.Attempts+1 {
328				return corrupt("attempts jump %d -> %d for %q", rec.Attempts, e.Attempts, e.ID)
329			}
330			if !validStatus(e.Status) || e.Status == StatusPending {
331				return corrupt("bad result status %q for %q", e.Status, e.ID)
332			}
333			switch e.Status {
334			case StatusWaiting:
335				if e.NextRetry != e.Now+nextRetryDelay(e.Attempts) {
336					return corrupt("waiting result has wrong retry schedule for %q", e.ID)
337				}
338			case StatusSuccess:
339				key := nonceKey(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
340				if e.ConsumeKey != key || e.ConsumeBy != e.ID {
341					return corrupt("success entry for %q carries mismatched nonce consumption", e.ID)
342				}
343				if winner, taken := s.consumed[key]; taken {
344					return corrupt("nonce %s already consumed by %q while accepting %q", key, winner, e.ID)
345				}
346				if e.NextRetry != 0 {
347					return corrupt("success entry for %q carries retry time", e.ID)
348				}
349				s.consumed[key] = e.ID
350			default: // terminal failure kinds
351				if e.NextRetry != 0 || e.ConsumeKey != "" || e.ConsumeBy != "" {
352					return corrupt("terminal entry for %q carries scheduling/consume fields", e.ID)
353				}
354			}
355			rec.Attempts = e.Attempts
356			rec.LastProcAt = e.Now
357			rec.Status = e.Status
358			rec.Reason = e.Reason
359			rec.NextRetry = e.NextRetry
360			if e.Now > s.now {
361				s.now = e.Now
362			}
363		case kindState:
364			// Compacted snapshot: the message already has >=1 attempts and the
365			// entry carries its full current status, so there is no attempts-jump
366			// invariant to check against prior result entries (there are none).
367			rec, ok := s.records[e.ID]
368			if !ok {
369				return corrupt("state for unknown id %q", e.ID)
370			}
371			if rec.Attempts != 0 {
372				return corrupt("duplicate state for id %q", e.ID)
373			}
374			if !validStatus(e.Status) || e.Status == StatusPending {
375				return corrupt("bad state status %q for %q", e.Status, e.ID)
376			}
377			if e.Attempts < 1 {
378				return corrupt("state with zero attempts for %q", e.ID)
379			}
380			switch e.Status {
381			case StatusWaiting:
382				if e.NextRetry != e.Now+nextRetryDelay(e.Attempts) {
383					return corrupt("state has wrong retry schedule for %q", e.ID)
384				}
385			case StatusSuccess:
386				key := nonceKey(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
387				if e.ConsumeKey != key || e.ConsumeBy != e.ID {
388					return corrupt("state for %q carries mismatched nonce consumption", e.ID)
389				}
390				if winner, taken := s.consumed[key]; taken {
391					return corrupt("nonce %s already consumed by %q while loading %q", key, winner, e.ID)
392				}
393				if e.NextRetry != 0 {
394					return corrupt("success state for %q carries retry time", e.ID)
395				}
396				s.consumed[key] = e.ID
397			default:
398				if e.NextRetry != 0 || e.ConsumeKey != "" || e.ConsumeBy != "" {
399					return corrupt("terminal state for %q carries scheduling/consume fields", e.ID)
400				}
401			}
402			rec.Attempts = e.Attempts
403			rec.LastProcAt = e.Now
404			rec.Status = e.Status
405			rec.Reason = e.Reason
406			rec.NextRetry = e.NextRetry
407			if e.Now > s.now {
408				s.now = e.Now
409			}
410		case kindAdvance:
411			if e.Now < s.now {
412				return corrupt("advance checkpoint %d before known time %d", e.Now, s.now)
413			}
414			s.now = e.Now
415		default:
416			return corrupt("unknown record type %q", e.T)
417		}
418		return nil
419	}
420	
421	func validStatus(s string) bool {
422		switch s {
423		case StatusPending, StatusWaiting, StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
424			return true
425		}
426		return false
427	}
428	
429	func (s *store) close() error {
430		if s.f == nil {
431			return nil
432		}
433		err := s.f.Sync()
434		cerr := s.f.Close()
435		s.f = nil
436		if err != nil {
437			return err
438		}
439		return cerr
440	}
441	
442	// forceClose releases the file without the final sync after a failed write.
443	func (s *store) forceClose() {
444		if s.f == nil {
445			return
446		}
447		s.f.Close()
448		s.f = nil
449	}
450	
451	// append writes one framed, checksummed, fsynced record.
452	func (s *store) append(e *logEntry) error {
453		if s.injectErr != nil {
454			return s.injectErr
455		}
456		body, err := json.Marshal(e)
457		if err != nil {
458			return fmt.Errorf("encode log entry: %w", err)
459		}
460		if _, err := s.f.Write(encodeFrame(body)); err != nil {
461			return fmt.Errorf("write %s: %w", logName, err)
462		}
463		if err := s.f.Sync(); err != nil {
464			return fmt.Errorf("sync %s: %w", logName, err)
465		}
466		if info, err := s.f.Stat(); err == nil {
467			s.size = info.Size()
468		} else {
469			s.size += int64(frameHeaderSize + len(body) + frameCRCsSize)
470		}
471		return nil
472	}
473	
474	// needsCompaction reports whether the log crossed the compaction threshold.
475	func (s *store) needsCompaction() bool {
476		return s.size > compactThreshold && s.snap != nil
477	}
478	
479	func (s *store) appendRegisterSource(chain string) error {
480		return s.append(&logEntry{T: kindSource, Chain: chain})
481	}
482	
483	func (s *store) appendHeader(h Header) error {
484		return s.append(&logEntry{T: kindHeader, Chain: h.Chain, Height: h.Height, Root: h.Root, Trusted: h.Trusted})
485	}
486	
487	func (s *store) appendSubmit(rec *Record) error {
488		m := rec.Msg.Message
489		return s.append(&logEntry{
490			T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
491			Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
492		})
493	}
494	
495	// appendResult records one processing outcome. On success the nonce
496	// consumption (consumeKey/consumeBy) is part of the same durable record,
497	// committing together atomically.
498	func (s *store) appendResult(now int64, rec *Record, status, reason string, attempts int, consumeKey, consumeBy string, success bool) error {
499		e := &logEntry{
500			T: kindResult, Now: now, ID: rec.Msg.Message.ID,
501			Status: status, Reason: reason, Attempts: attempts,
502		}
503		if status == StatusWaiting {
504			e.NextRetry = now + nextRetryDelay(attempts)
505		}
506		if success {
507			e.ConsumeKey = consumeKey
508			e.ConsumeBy = consumeBy
509		}
510		return s.append(e)
511	}
512	
513	func (s *store) appendAdvance(now int64) error {
514		return s.append(&logEntry{T: kindAdvance, Now: now})
515	}
516	
517	// compact atomically replaces the log with a deterministic snapshot of live
518	// state. It must run while Queue.mu is held (no concurrent mutation), and only
519	// after in-memory state reflects every acknowledged append.
520	func (s *store) compact(state *loadedState) error {
521		entries := []*logEntry{{T: kindVersion, V: currentLogV}}
522	
523		chains := make([]string, 0, len(state.sources))
524		for c := range state.sources {
525			chains = append(chains, c)
526		}
527		sort.Strings(chains)
528		for _, c := range chains {
529			entries = append(entries, &logEntry{T: kindSource, Chain: c})
530		}
531	
532		headerChains := make([]string, 0, len(state.headers))
533		for c := range state.headers {
534			headerChains = append(headerChains, c)
535		}
536		sort.Strings(headerChains)
537		for _, c := range headerChains {
538			h := state.headers[c]
539			entries = append(entries, &logEntry{T: kindHeader, Chain: h.Chain, Height: h.Height, Root: h.Root, Trusted: h.Trusted})
540		}
541	
542		seqs := make([]int64, 0, len(state.records))
543		bySeq := make(map[int64]*Record, len(state.records))
544		for _, rec := range state.records {
545			seqs = append(seqs, rec.Seq)
546			bySeq[rec.Seq] = rec
547		}
548		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
549		for _, seq := range seqs {
550			rec := bySeq[seq]
551			m := rec.Msg.Message
552			entries = append(entries, &logEntry{
553				T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
554				Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
555			})
556			if rec.Attempts > 0 {
557				re := &logEntry{
558					T: kindState, Now: rec.LastProcAt, ID: m.ID,
559					Status: rec.Status, Reason: rec.Reason, Attempts: rec.Attempts,
560				}
561				if rec.Status == StatusWaiting {
562					re.NextRetry = rec.NextRetry
563				}
564				if rec.Status == StatusSuccess {
565					re.ConsumeKey = nonceKey(m.From, m.To, m.Nonce)
566					re.ConsumeBy = m.ID
567				}
568				entries = append(entries, re)
569			}
570		}
571		if state.now > 0 {
572			entries = append(entries, &logEntry{T: kindAdvance, Now: state.now})
573		}
574	
575		tmp := filepath.Join(s.dir, logName+".compact")
576		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, compactFileMode)
577		if err != nil {
578			return err
579		}
580		abort := func(err error) error {
581			f.Close()
582			os.Remove(tmp)
583			return err
584		}
585		if _, err := f.WriteString(logMagic); err != nil {
586			return abort(err)
587		}
588		for _, e := range entries {
589			body, err := json.Marshal(e)
590			if err != nil {
591				return abort(err)
592			}
593			if _, err := f.Write(encodeFrame(body)); err != nil {
594				return abort(err)
595			}
596		}
597		if err := f.Sync(); err != nil {
598			return abort(err)
599		}
600		if err := f.Close(); err != nil {
601			os.Remove(tmp)
602			return err
603		}
604		if err := os.Rename(tmp, filepath.Join(s.dir, logName)); err != nil {
605			os.Remove(tmp)
606			return err
607		}
608		if err := syncDir(s.dir); err != nil {
609			return err
610		}
611		nf, err := os.OpenFile(filepath.Join(s.dir, logName), os.O_RDWR|os.O_APPEND, compactFileMode)
612		if err != nil {
613			return err
614		}
615		if _, err := nf.Seek(0, io.SeekEnd); err != nil {
616			nf.Close()
617			return err
618		}
619		s.f.Close()
620		s.f = nf
621		if info, err := nf.Stat(); err == nil {
622			s.size = info.Size()
623		}
624		return nil
625	}
626	
627	// syncDir fsyncs a directory so that file creation and rename survive a crash.
628	func syncDir(dir string) error {
629		d, err := os.Open(dir)
630		if err != nil {
631			return fmt.Errorf("open directory for sync: %w", err)
632		}
633		defer d.Close()
634		if err := d.Sync(); err != nil {
635			return fmt.Errorf("sync directory %s: %w", dir, err)
636		}
637		return nil
638	}
