535	// Corrupt and unsupported formats must be rejected, never silently cleared.
536	func TestCorruptionRejected(t *testing.T) {
537		cases := map[string][]byte{
538			"foreign magic":   []byte("NOT-A-RELAYPROOF-LOG!!\n"),
539			"truncated magic": []byte("RELAY"),
540			"empty":           nil,
541			"bad version":     append([]byte(logMagic), encodeFrame(mustMarshal(&logEntry{T: "version", V: 9}))...),
542		}
543		for name, data := range cases {
544			t.Run(name, func(t *testing.T) {
545				dir := t.TempDir()
546				path := filepath.Join(dir, logName)
547				if err := os.WriteFile(path, data, 0o600); err != nil {
548					t.Fatal(err)
549				}
550				q, err := Open(dir)
551				if !errors.Is(err, ErrCorrupt) {
552					if q != nil {
553						q.Close()
554					}
555					t.Fatalf("want ErrCorrupt, got %v", err)
556				}
557				// Original bytes must still be there (not wiped).
558				got, err := os.ReadFile(path)
559				if err != nil {
560					t.Fatal(err)
561				}
562				if name == "empty" {
563					if len(got) != 0 {
564						t.Fatalf("empty file must not be rewritten on failed open")
565					}
566				} else if len(got) != len(data) {
567					t.Fatalf("corrupt state was modified: %d -> %d bytes", len(data), len(got))
568				}
569			})
570		}
571	}
