629		q.store.injectErr = errors.New("disk on fire")
630		if _, err := q.Submit(env("m", "a", "b", 1, 10, 0)); !errors.Is(err, ErrStorage) {
631			t.Fatalf("want ErrStorage, got %v", err)
632		}
633		// Further writes must fail loudly instead of corrupting the log.
634		if err := q.RegisterSource("c"); !errors.Is(err, ErrStorage) {
635			t.Fatalf("broken queue must refuse writes, got %v", err)
636		}
637		q.Close()
