652	// Concurrent goroutines sharing one Queue must never double-consume a nonce.
653	func TestConcurrentNoDoubleConsume(t *testing.T) {
654		q, _ := openTempQueue(t)
655		defer q.Close()
656		q.RegisterSource("a")
657		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
658	
659		const n = 40
660		var wg sync.WaitGroup
661		for i := 0; i < n; i++ {
662			wg.Add(1)
663			go func(i int) {
664				defer wg.Done()
665				_, _ = q.Submit(env(fmt.Sprintf("m%d", i), "a", "b", uint64(i%3), 10, 0))
666			}(i)
667		}
668		wg.Wait()
669		rep, err := q.Advance(1000)
670		if err != nil {
671			t.Fatal(err)
672		}
673		delivered := map[uint64]int{}
674		for _, res := range rep.Results {
675			if res.Status == StatusSuccess {
676				delivered[q.records[res.ID].Msg.Message.Nonce]++
677			}
678		}
679		if len(delivered) != 3 {
680			t.Fatalf("want exactly 3 consumed nonces, got %d", len(delivered))
681		}
682		for nonce, count := range delivered {
683			if count != 1 {
684				t.Fatalf("nonce %d delivered %d times", nonce, count)
685			}
686		}
687		replays := 0
688		for _, res := range rep.Results {
689			if res.Status == StatusReplay {
690				replays++
691			}
692		}
693		if replays != n-3 {
694			t.Fatalf("want %d replays, got %d", n-3, replays)
695		}
696		if len(q.consumed) != 3 {
697			t.Fatalf("consumed set: %v", q.consumed)
698		}
699	}
