227	// longest intact prefix and the reconstructed state.
228	func replayLog(raw []byte) (int64, *loadedState, error) {
229		if !bytes.HasPrefix(raw, []byte(logMagic)) {
230			return 0, nil, fmt.Errorf("%w: missing %s header", ErrCorrupt, logMagic)
231		}
232		pos := len(logMagic)
233		state := &loadedState{
234			sources:  map[string]bool{},
235			headers:  map[string]Header{},
236			records:  map[string]*Record{},
237			consumed: map[string]string{},
238		}
239	
240		sawVersion := false
241		for pos < len(raw) {
242			// Need at least the length header.
243			if len(raw)-pos < frameHeaderSize {
244				return int64(pos), state, nil // torn length header of an unacked write
245			}
246			n := int(binary.BigEndian.Uint32(raw[pos : pos+frameHeaderSize]))
247			if n == 0 {
248				return 0, nil, fmt.Errorf("%w: zero-length record at offset %d", ErrCorrupt, pos)
249			}
250			bodyStart := pos + frameHeaderSize
251			frameEnd := bodyStart + n + frameCRCsSize
252			if frameEnd > len(raw) {
253				return int64(pos), state, nil // torn body/CRC of an unacked write
254			}
255			payload := raw[bodyStart : bodyStart+n]
256			wantCRC := binary.BigEndian.Uint32(raw[bodyStart+n : frameEnd])
257			if crc32.Checksum(payload, crcTable) != wantCRC {
258				if frameEnd == len(raw) {
259					// Torn sectors of the final, unacknowledged frame.
260					return int64(pos), state, nil
261				}
262				return 0, nil, fmt.Errorf("%w: checksum mismatch at offset %d", ErrCorrupt, pos)
263			}
264			var e logEntry
265			if err := json.Unmarshal(payload, &e); err != nil {
266				return 0, nil, fmt.Errorf("%w: invalid record at offset %d: %v", ErrCorrupt, pos, err)
267			}
268			if !sawVersion {
269				if e.T != kindVersion || e.V != currentLogV {
270					return 0, nil, fmt.Errorf("%w: unsupported log version entry: %+v", ErrCorrupt, e)
271				}
272				sawVersion = true
